// apps/dashboard/server/audit.ts
import { randomUUID as randomUUID4 } from "node:crypto";
async function appendAudit(db2, env2, record) {
  const { severity } = requireEvent(record.eventId);
  await db2.appendAudit({
    id: randomUUID4(),
    guildId: record.guildId,
    severity,
    eventId: record.eventId,
    correlationId: record.correlationId ?? randomUUID4(),
    actorHash: signActor(record.actorId, env2.eventHmacSecret),
    sourceLayer: record.sourceLayer ?? "dashboard-bff",
    payloadCiphertext: encryptSecret(JSON.stringify(record.payload), env2.encryptionKey)
  });
}

// apps/dashboard/server/guild-access.ts
function isAdministrable(permissions) {
  return hasPermission(permissions, DISCORD_PERMISSION_BITS.MANAGE_GUILD);
}
function describeGuildAccess(input) {
  const { guild, botPresent } = input;
  const tier = botPresent ? input.tier : null;
  return {
    id: guild.id,
    name: guild.name,
    iconUrl: guildIconUrl(guild.id, guild.icon),
    memberCount: botPresent ? input.memberCount : null,
    tier,
    botPresent,
    canManage: isAdministrable(guild.permissions),
    canManageIdentity: tier !== null,
    canManageLogging: tier !== null,
    canManageCommands: tier !== null,
    // Role mapping decides who can do everything else, so it needs the admin
    // tier or above — a moderator must not be able to widen their own access by
    // editing the list.
    canManageTiers: tier === "owner" || tier === "admin",
    canInvite: hasPermission(guild.permissions, DISCORD_PERMISSION_BITS.MANAGE_GUILD),
    // Mirrors `requireInstanceAdmin` in the route: administer a guild the bot
    // actually serves. Kept here so the selector and the gate cannot drift, and
    // so a moderator of one server never sees the deployment's network reach.
    canAdminInstance: botPresent && isAdministrable(guild.permissions)
  };
}

